const bilingual=(az,en)=>window.siteLanguage==='en'?en:az;
const articleData=()=>window.siteLanguage==='en'?window.EN_CONTENT.article:window.OCT_CONTENT.article;
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toumaiHTML(){return `<section class="toumai-section wrap section"><div class="toumai-visual"><img src="/assets/toumai-system.png" width="450" height="259" loading="lazy" alt="Toumai — ${bilingual('robotik sistem, görüntüləmə bölməsi və cərrah konsolu','robotic system, imaging unit and surgeon console')}"></div><div class="toumai-copy"><h2>${bilingual('Toumai robotik cərrahiyyə sistemi','Toumai robotic surgery system')}</h2><p>${bilingual('Robotik qollar, görüntüləmə sistemi və cərrah konsolu.','Robotic arms, imaging system and surgeon console.')}</p><a class="button primary" href="/robotik-cerrahiyye/">${bilingual('Robotik cərrahiyyə nədir?','What is robotic surgery?')}<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg></a></div></section>`}
function blogTeaser(){const a=articleData();return `<section class="wrap section home-blog" id="bloq"><div><h2>${bilingual('Bloq','Blog')}</h2><p>${bilingual('Robotik cərrahiyyə haqqında.','About robotic surgery.')}</p></div><a class="blog-feature" href="/bloq/azerbaycanda-ilk-robotik-cerrahiyye/"><h3>${a.title}</h3><p>${bilingual('Robotik prostat cərrahiyyəsi və onun imkanları.','Robotic prostate surgery and its capabilities.')}</p><span class="text-link">${bilingual('Məqaləni oxu','Read the article')} <svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg></span></a></section>`}
function articleParagraph(p,i){
 const az=[['Azərbaycanda robotik   cərrahiyyə','robotik cərrahiyyə'],['Robotik cərrahiyyə'],['Robotik prostat əməliyyatı'],['robotik cərrahiyyə']];
 const en=[['robotic surgery'],['robotic surgery'],['robotic prostate surgery'],['robotic surgery']];
 let html=escapeHTML(p);
 for(const term of (window.siteLanguage==='en'?en:az)[i]||[])html=html.replace(term,'<strong>'+term+'</strong>');
 return '<p>'+html+'</p>';
}
function renderBlog(){
 const a=articleData();pageTitle(a.title);
 const content=a.paragraphs.map((p,i)=>p.includes('•')
  ?'<ul>'+p.split('•').map(x=>x.replace(/\u2060/g,'').trim()).filter(Boolean).map(x=>'<li>'+escapeHTML(x)+'</li>').join('')+'</ul>'
  :i===4?'<h2>'+escapeHTML(p)+'</h2>':articleParagraph(p,i)).join('');
 main.innerHTML=`<div class="wrap blog-reading">${bread(bilingual('Bloq','Blog'))}<article class="article-body blog-article" aria-labelledby="article-title"><header class="detail-header blog-heading"><h1 id="article-title">${escapeHTML(a.title)}</h1></header>${content}<div class="article-next"><a class="text-link" href="/robotik-cerrahiyye/">${bilingual('Robotik cərrahiyyə nədir?','What is robotic surgery?')} <svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg></a></div></article></div>${contactHTML()}`;
}
document.addEventListener('DOMContentLoaded',()=>{
 const host=document.createElement('aside');host.className='faq-assistant';
 host.innerHTML=`<button class="assistant-toggle" aria-expanded="false" aria-controls="assistant-panel"><svg viewBox="0 0 24 24" class="ui-icon" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M20 11a8 8 0 0 1-8 8H5l-4 3 2-6a8 8 0 1 1 17-5Z"/><path d="M7 10h9M7 14h6"/></svg>${bilingual('Sualınız var?','Have a question?')}</button><section id="assistant-panel" hidden aria-labelledby="assistant-title"><div class="assistant-header"><h2 id="assistant-title">${bilingual('Robotik cərrahiyyə haqqında','About robotic surgery')}</h2><button class="assistant-close" aria-label="${bilingual('Bağla','Close')}">×</button></div><p class="assistant-intro">${bilingual('Saytdakı sual-cavablardan məlumat alın.','Find information from the website’s questions and answers.')}</p><div class="assistant-topics">${window.siteFAQs.map(([q],i)=>`<button type="button" data-topic="${i}">${escapeHTML(q)}</button>`).join('')}</div><div class="assistant-answer" aria-live="polite"></div><form class="assistant-form"><label for="assistant-question">${bilingual('Sualınızı yazın','Enter your question')}</label><div><input id="assistant-question" maxlength="300" autocomplete="off" required><button type="submit">${bilingual('Göndər','Send')}</button></div></form></section>`;
 document.body.append(host);const toggle=host.querySelector('.assistant-toggle'),panel=host.querySelector('section'),answer=host.querySelector('.assistant-answer');
 const setOpen=open=>{panel.hidden=!open;toggle.setAttribute('aria-expanded',String(open));if(open)host.querySelector('.assistant-close').focus();else toggle.focus()};
 toggle.onclick=()=>setOpen(panel.hidden);host.querySelector('.assistant-close').onclick=()=>setOpen(false);host.addEventListener('keydown',e=>{if(e.key==='Escape'&&!panel.hidden)setOpen(false)});
 const show=i=>{const [q,a]=window.siteFAQs[i];answer.innerHTML='<h3>'+escapeHTML(q)+'</h3>'+a;answer.scrollIntoView({block:'nearest',behavior:'auto'})};
 host.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>show(Number(b.dataset.topic)));
 host.querySelector('form').onsubmit=e=>{e.preventDefault();const q=host.querySelector('input').value.trim().toLocaleLowerCase('az');const terms=[['robot həyata','kim edir','who operates','perform the operation','robot operate'],['üstün','fayda','advantage','benefit'],['sahə','field','specialt','tətbiq','application'],['uyğun','hər kəs','bütün pasiyent','suitable','every patient'],['cərrahın rolu','surgeon’s role','surgeon role','nəzarət','control'],['ağrı','pain','sağal','recovery']];const i=terms.findIndex(list=>list.some(word=>q.includes(word)));if(i>=0)show(i);else answer.textContent=bilingual('Bu sual üçün hazır cavab yoxdur. Yuxarıdakı mövzulardan birini seçin və ya mərkəzlə əlaqə saxlayın.','There is no prepared answer for this question. Choose one of the topics above or contact the centre.');};
});
